\section*{Definitions}

Let $V$ be a non-empty set and $R \subseteq V \times V$ be a binary relation.
\begin{definition}
    For any $v \in V$, the \textbf{$1$-neighborhood} is defined as $\Gamma(v) = \{u \in V \mid (v,u) \in R\}$. Higher-order neighborhoods are defined inductively by $\Gamma^0(v) = \{v\}$ and $\Gamma^j(v) = \bigcup_{u \in \Gamma^{j-1}(v)} \Gamma(u)$ for $j \ge 1$.
\end{definition}

\begin{definition}
    The relation $R$ is:
    \begin{enumerate}
        \item \textbf{Reflexive} if $(v,v) \in R$ for all $v \in V$ (implying $v \in \Gamma(v)$ and $\Gamma^{j-1}(v) \subseteq \Gamma^j(v)$).
        \item \textbf{Point-symmetric} (or vertex-transitive) if for any pair of vertices $u, w \in V$, there exists an automorphism $\sigma \in \text{Aut}(V, R)$ such that $\sigma(u) = w$.
    \end{enumerate}
\end{definition}
Because $R$ is point-symmetric, the cardinalities $d = |\Gamma(v)|$ and $|\Gamma^j(v)|$ are independent of the choice of $v \in V$.

\section*{Main Theorem}

\begin{theorem}
Let $(V, R)$ be a point-symmetric, reflexive relation. For any vertex $v \in V$ and any integer $j \ge 1$,
\[
|\Gamma^j(v)| \ge |\Gamma^{j-1}(v)| + |\Gamma(v)| - 1.
\]
\end{theorem}

\begin{proof}[Proof Sketch]
Let $k = |\Gamma(v)|$. If $|\Gamma^{j-1}(v)| = |\Gamma^j(v)|$, the relation stabilizes and the bound holds trivially. Otherwise, choose a vertex $u \in \Gamma^{j-1}(v) \setminus \Gamma^{j-2}(v)$ (where $\Gamma^{-1}(v) = \emptyset$). 

By point-symmetry, there exists an automorphism mapping $v$ to $u$, which maps $\Gamma(v)$ to $\Gamma(u)$. Since $(V,R)$ is reflexive, $u \in \Gamma(u) \subseteq \Gamma^j(v)$. By selecting an extremal vertex on the boundary of $\Gamma^{j-1}(v)$, it can be shown that $\Gamma(u)$ can contain at most one element already in $\Gamma^{j-1}(v)$ (specifically $u$ itself), adding at least $|\Gamma(v)| - 1$ distinct new elements to $\Gamma^j(v)$.
\end{proof}

\section*{Key Corollaries}

\begin{corollary}[Linear Growth Bound]
For any vertex $v \in V$ and $j \ge 0$,
\[
|\Gamma^j(v)| \ge j(|\Gamma(v)| - 1) + 1.
\]
\end{corollary}
\begin{proof}
Follows directly by induction on $j$, using the base case $|\Gamma^0(v)| = 1$.
\end{proof}

\begin{corollary}[Upper Bound on Diameter]
Let $(V,R)$ be a finite, connected, point-symmetric reflexive relation (or graph) with $|V| = n$, vertex degree $d = |\Gamma(v)| \ge 2$, and diameter $D$. Then:
\[
D \le \frac{n - 1}{d - 1}.
\]
\end{corollary}
\begin{proof}
By definition of diameter $D$, $\Gamma^D(v) = V$, so $|\Gamma^D(v)| = n$. Applying the linear growth corollary at $j = D$:
\[
n = |\Gamma^D(v)| \ge D(d - 1) + 1 \implies D \le \frac{n - 1}{d - 1}.
\]
\end{proof}

